{
  "name": "@intisy-ai/plugin-updater",
  "version": "1.15.0",
  "description": "Plugin lifecycle manager for OpenCode and Claude Code launchers",
  "type": "module",
  "main": "dist/index.js",
  "pluginEntry": "dist/plugin.js",
  "bin": {
    "plugin-updater": "dist/cli.js"
  },
  "license": "MIT",
  "author": "intisy",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/intisy-ai/plugin-updater.git"
  },
  "keywords": [
    "opencode",
    "claude",
    "plugin",
    "updater",
    "lifecycle"
  ],
  "files": [
    "dist/",
    "plugin.json",
    "README.md",
    "LICENSE"
  ],
  "engines": {
    "node": ">=20.0.0"
  },
  "scripts": {
    "build": "tsc && node build.mjs",
    "postbuild": "node dist/index.js readme",
    "test": "npm run build && vitest run",
    "prepublishOnly": "npm run build"
  },
  "devDependencies": {
    "@types/node": "^22.0.0",
    "esbuild": "^0.25.12",
    "typescript": "^5.0.0",
    "vitest": "^3.2.6"
  },
  "dependencies": {
    "@intisy-ai/api": "^1.0.2",
    "@intisy-ai/core": "^2.5.0"
  }
}

#!/usr/bin/env node
// Before any dynamic import of the plugin entry, so importing it cannot start an update sequence.
process.env.INTISY_PLUGIN_LIBRARY_MODE = "1";
process.env.PLUGIN_UPDATER_LIBRARY_MODE = "1";
process.env.PLUGIN_UPDATER_CLI = "1";
import fs from "fs";
import path from "path";
import os from "os";
import { resolveInitApps, cwdApp, registerUpdaterWithApp } from "./init.js";
import { getAppConfigDir, getReposDir, getPluginDir } from "./env.js";
import { registerPluginEntry, removePluginEntry } from "./manage.js";
// @ts-ignore — generated bundle, no .d.ts
import { getApps } from "@intisy-ai/core";
const UPDATER_NAME = "plugin-updater";
function parseArgs(argv) {
    const parsed = { command: argv[0] ?? "", urls: [] };
    for (let i = 1; i < argv.length; i++) {
        if (argv[i] === "--app")
            parsed.app = argv[++i];
        else if (argv[i] === "--branch")
            parsed.branch = argv[++i];
        else if (argv[i] === "--sync")
            parsed.sync = true;
        else
            parsed.urls.push(argv[i]);
    }
    return parsed;
}
function binaryExists(name) {
    try {
        const probe = process.platform === "win32" ? `where ${name}` : `command -v ${name}`;
        require("child_process").execSync(probe, { stdio: "ignore", windowsHide: true });
        return true;
    }
    catch {
        return false;
    }
}
// An explicit --app is accepted for the two built-ins OR any app registered in the
// shared app registry (not just claude/opencode) — getConfigDir below then resolves
// it through that same registry.
function detectApp(explicit) {
    if (explicit === "claude" || explicit === "opencode")
        return explicit;
    if (explicit) {
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        if (getApps().some((a) => a.id === explicit))
            return explicit;
        throw new Error(`Unknown app "${explicit}" - use claude, opencode, or a registered app id`);
    }
    const hasClaudeDir = fs.existsSync(path.join(os.homedir(), ".claude"));
    const hasOpencodeDir = fs.existsSync(path.join(os.homedir(), ".opencode"))
        || fs.existsSync(path.join(os.homedir(), ".config", "opencode"));
    if (hasClaudeDir !== hasOpencodeDir)
        return hasClaudeDir ? "claude" : "opencode";
    const hasClaudeBin = binaryExists("claude");
    const hasOpencodeBin = binaryExists("opencode");
    if (hasClaudeBin !== hasOpencodeBin)
        return hasClaudeBin ? "claude" : "opencode";
    throw new Error("Both apps (or neither) found - pass --app claude or --app opencode");
}
// Delegates to env.ts's getAppConfigDir, which resolves through the shared app
// registry first (any custom app, once registered) before falling back to the
// two built-in layouts — avoiding a second hardcoded copy of that resolution here.
function getConfigDir(app) {
    return getAppConfigDir(app);
}
function readJson(file) {
    try {
        return JSON.parse(fs.readFileSync(file, "utf8").replace(/^\s*\/\/[^\n]*/gm, ""));
    }
    catch {
        return null;
    }
}
function pluginsJsonPath(configDir) {
    return path.join(configDir, "config", "plugins.json");
}
// which apps are installed on this machine (used when no --app is given)
function presentApps() {
    const claude = fs.existsSync(path.join(os.homedir(), ".claude")) || binaryExists("claude");
    const opencode = fs.existsSync(path.join(os.homedir(), ".opencode"))
        || fs.existsSync(path.join(os.homedir(), ".config", "opencode"))
        || binaryExists("opencode");
    return { claude, opencode };
}
// A plain one-line prompt (NOT a menu/TUI) shown when both/neither app is detected and no
// --app was passed: the user just types which app to install for. defaultApp (cwd-inferred)
// may be null — then an empty answer re-asks rather than guessing. Non-interactive callers
// never reach this (resolveInitApps hard-errors instead).
async function promptInitApps(_present, defaultApp) {
    const readline = await import("readline/promises");
    const rl = readline.createInterface({ input: process.stdin, output: process.stdout });
    try {
        const hint = defaultApp ? `claude/opencode/both, default ${defaultApp}` : "claude/opencode/both";
        for (;;) {
            const ans = (await rl.question(`Install plugin-updater for which app? (${hint}): `)).trim().toLowerCase();
            if (ans === "claude" || ans === "c")
                return ["claude"];
            if (ans === "opencode" || ans === "o")
                return ["opencode"];
            if (ans === "both" || ans === "b")
                return ["opencode", "claude"];
            if (ans === "") {
                if (defaultApp === "both")
                    return ["opencode", "claude"];
                if (defaultApp)
                    return [defaultApp];
            }
            console.log('Please type "claude", "opencode", or "both".');
        }
    }
    finally {
        rl.close();
    }
}
async function setupEntry(updater, configDir, url, branch, sync) {
    const entry = registerPluginEntry(configDir, url, { branch, sync });
    const file = path.join(configDir, "config", "plugins.json");
    if (entry.added)
        console.log(`Added ${entry.name} to ${file}`);
    else if (entry.changed)
        console.log(`Enabled sync on ${entry.name} in ${file}`);
    else if (entry.syncEnabled)
        console.log(`${entry.name} already present (sync on) in ${file}`);
    else
        console.log(`${entry.name} already present in ${file}`);
    console.log(`Setting up ${entry.name}...`);
    try {
        await updater.updatePluginPublic(entry.name, entry.url, entry.branch);
    }
    catch (e) {
        removePluginEntry(configDir, entry.name);
        throw e;
    }
}
async function main() {
    const parsed = parseArgs(process.argv.slice(2));
    if (!["init", "add", "run", "remove"].includes(parsed.command)) {
        console.log("usage: plugin-updater <init|add|remove|run> [git-urls-or-names...] [--app claude|opencode] [--branch name] [--sync]");
        process.exit(parsed.command ? 1 : 0);
    }
    const updater = await import("./index.js");
    // `init` may target one or both apps: explicit --app wins; otherwise a single
    // detected app is used, and an ambiguous (both/neither) interactive run is prompted.
    if (parsed.command === "init") {
        const apps = await resolveInitApps(parsed.app, {
            present: presentApps,
            isTTY: Boolean(process.stdin.isTTY),
            cwdApp,
            prompt: promptInitApps,
        });
        for (const app of apps) {
            process.env.PLUGIN_UPDATER_APP = app;
            const configDir = getConfigDir(app);
            if (!fs.existsSync(configDir))
                fs.mkdirSync(configDir, { recursive: true });
            console.log(`App: ${app} (${configDir})`);
            const registration = registerUpdaterWithApp(configDir, app);
            console.log(registration.changed
                ? `Registered ${UPDATER_NAME} in ${registration.target}`
                : `${UPDATER_NAME} already registered in ${registration.target}`);
            for (const url of parsed.urls) {
                await setupEntry(updater, configDir, url, parsed.branch, parsed.sync);
            }
        }
        console.log("Init complete.");
        return;
    }
    const app = detectApp(parsed.app);
    process.env.PLUGIN_UPDATER_APP = app;
    const configDir = getConfigDir(app);
    if (!fs.existsSync(configDir))
        fs.mkdirSync(configDir, { recursive: true });
    console.log(`App: ${app} (${configDir})`);
    if (parsed.command === "add") {
        if (parsed.urls.length === 0)
            throw new Error("add requires at least one git url");
        for (const url of parsed.urls) {
            await setupEntry(updater, configDir, url, parsed.branch, parsed.sync);
        }
    }
    else if (parsed.command === "remove") {
        if (parsed.urls.length === 0)
            throw new Error("remove requires at least one plugin name");
        for (const arg of parsed.urls) {
            const name = arg.replace(/\.git$/, "").split("/").pop() ?? arg;
            removePluginEntry(configDir, name);
            try {
                fs.rmSync(path.join(getReposDir(configDir), name), { recursive: true, force: true });
            }
            catch { /* ignore */ }
            try {
                fs.rmSync(path.join(getPluginDir(configDir), `${name}.js`), { force: true });
            }
            catch { /* ignore */ }
            console.log(`Removed ${name}`);
        }
    }
    else {
        const entries = readJson(pluginsJsonPath(configDir)) ?? [];
        // the CLI is how a loader asks for a run; the app path is activate() at module load
        await updater.earlyLaunch(configDir, entries, { trigger: "loader" });
    }
}
// Explicitly exit once the run completes. Dynamically-imported plugin/loader
// modules (deploy.ts) can leave the event loop non-empty (e.g. keepalive refs),
// which would otherwise hang this task-runner and stall CC's SessionStart hook.
// Detached daemons are already unref'd, so they survive the parent exiting.
main()
    .then(() => process.exit(0))
    .catch((e) => {
    console.error(String(e.message ?? e));
    process.exit(1);
});

import { getAppConfigDir, getAppName, getReposDir, isOpencodeHookInvocation, setEarlyLaunchConfigDir, getPluginDir, isLibraryMode, isHostActivation, setHostActivation } from "./env.js";
import { writeLog } from "./log.js";
import { getPlugins, getPluginsPath, readOpencodeJson, setPluginCommitHash } from "./config.js";
import { selfUpdate, updateNpmPlugin, resolveNpmPluginVersion } from "./npm.js";
import { updatePlugin, getLocalHead } from "./git.js";
import { deployToExecutionDir } from "./deploy.js";
import { syncAllAcrossApps } from "./syncbridge.js";
import { checkUpdates, runAutoUpdate, updateOne as updateOneInHome, updateAll as updateAllInHome } from "./updates.js";
import { resolveMode } from "./policy.js";
import { resolveBranch, tracksExperimental } from "./channel.js";
import { readUpdateCache, writeUpdateCache } from "./cache.js";
import { deployedIdFor, readCloneManifest, DEPLOYED_SUFFIXES } from "./manifest.js";
import { UPDATER_NAME, UPDATER_SETTINGS, updaterSchema, readUpdaterConfig } from "./schema.js";
// @ts-ignore — generated bundle, no .d.ts
// @ts-ignore — generated bundle, no .d.ts
import { loadConfig, defineReadme, maybeRunReadmeCli, registerApp, withCause, setActivityContext, getActivityContext, resetActivityContext } from "@intisy-ai/core";
import path from "path";
import fs from "fs";
import { libraryManagement, pluginManagement } from "./manage.js";
import { emitPluginInstalled, emitPluginUpdated, emitPluginUpdateFailed, emitPluginActivated, emitPluginUninstalled, emitPluginDowngraded, } from "./pluginActivity.js";
// This bundle's core instance is only ever used by this plugin, so naming the entry
// once here is accurate for every event it emits, including the ones outside a run.
setActivityContext({ entry: "updater" });
defineReadme({
    description: "Plugin lifecycle manager for OpenCode and Claude Code launchers. Handles install, update, rebuild, downgrade, and uninstall operations for all plugins.",
    architecture: `flowchart TD
    %% Triggers
    subgraph Execution_Triggers [Execution Triggers]
        CLI_BOOT[CLI Startup (claude/oc)]
        TUI_MENU[Launcher TUI Actions]

        CLI_BOOT -->|Auto-runs hook on start| UPDATER_CORE
        TUI_MENU -->|Manual rebuild/downgrade/uninstall| UPDATER_CORE
    end

    %% Core Logic
    subgraph Plugin_Updater [Updater Core Logic]
        UPDATER_CORE[Updater Engine]
        API_LAYER[global.OpenCodeAPI Interop]
        GIT_MGR[Git Operations Manager]
        DEPLOYER[Plugin Deployer]

        UPDATER_CORE <-->|Requests repo paths| API_LAYER
        UPDATER_CORE -->|Trigger sync| GIT_MGR
        UPDATER_CORE -->|Trigger deploy| DEPLOYER
    end

    %% External & Storage
    subgraph Storage_and_Network [Storage & External]
        GH_REPOS[GitHub (intisy-ai/plugin-*)]
        LOCAL_WORKSPACE[(.config/github/repos/intisy-ai/)]
        CC_PLUGINS[(.claude/plugin/)]
        OC_PLUGINS[(.config/opencode/plugin/)]

        GIT_MGR <-->|git clone/pull| GH_REPOS
        GIT_MGR -->|Updates source| LOCAL_WORKSPACE
        DEPLOYER -->|Copies compiled output| CC_PLUGINS
        DEPLOYER -->|Copies compiled output| OC_PLUGINS
    end`,
    structure: {
        src: ["TypeScript source (`index` engine + `git`, `npm`, `deploy`, `config`, `log`, `env`, `syncbridge`, `cli`, `commands`)."],
        dist: ["`dist/index.js` — the plugin entry; `dist/cli.js` — the `plugin-updater` bin."],
    },
    dependencies: ["core", "sync-bridge"],
    extraSections: [
        {
            id: "adding-plugins",
            title: "Adding plugins",
            after: "installation",
            body: `plugin-updater is the one plugin added directly to OpenCode's \`opencode.jsonc\` (every other plugin goes through \`plugins.json\`); the loaders also resolve and run it on startup. To register a plugin from the CLI:
\`\`\`bash
plugin-updater add https://github.com/intisy-ai/<plugin>      # register a git plugin
plugin-updater add https://github.com/intisy-ai/<plugin> --sync  # …and mirror it to the other app
\`\`\``,
        },
        {
            id: "sync",
            title: "Cross-app plugin sync (`sync: true`)",
            after: "adding-plugins",
            body: `A \`plugins.json\` entry flagged \`sync: true\` is mirrored into the **other** app's \`plugins.json\`, so a plugin enabled in OpenCode is also installed in Claude Code (and vice versa). At the start of \`earlyLaunch\`, plugin-updater loads [sync-bridge](https://github.com/intisy-ai/sync-bridge)'s library bundle (\`dist/lib.js\`) and calls \`syncPlugins()\`, then re-reads the list so a freshly-synced-in plugin is cloned and built in the **same** launch. It is additive (never removes) and a no-op when sync-bridge isn't installed.

\`\`\`jsonc
{ "name": "antigravity-auth", "url": "https://github.com/intisy-ai/antigravity-auth", "enabled": true, "autoUpdate": false, "sync": true }
\`\`\`

Set it from the CLI with \`--sync\`:
\`\`\`bash
plugin-updater add https://github.com/intisy-ai/antigravity-auth --sync
\`\`\``,
        },
        {
            id: "api",
            title: "API",
            after: "sync",
            body: `| Method | Description |
|---|---|
| \`rebuild(pluginItem)\` | Pull latest and redeploy |
| \`downgrade(pluginItem, commitHash)\` | Checkout specific commit |
| \`disable(pluginItem)\` | Cleanup on disable |
| \`uninstall(pluginItem)\` | Remove repo and deployed files |
| \`registerTests(testApi)\` | Register sync verification tests |`,
        },
        {
            id: "host-signals",
            title: "Host signals",
            after: "api",
            body: `A host sets one of these environment variables to tell this plugin what it is doing. The \`INTISY_PLUGIN_*\` name is the contract; the \`PLUGIN_UPDATER_*\` name is accepted for a host built before the generic name existed.

| Signal | Meaning |
|---|---|
| \`INTISY_PLUGIN_LIBRARY_MODE\` (or \`PLUGIN_UPDATER_LIBRARY_MODE\`) | The host imported this module for its API, not to activate it, so no update sequence runs on import. |
| \`INTISY_PLUGIN_ACTIVATION\` (or \`PLUGIN_UPDATER_ACTIVATION\`) | An activation is already being driven, so this plugin must not start another and recurse. |`,
        },
    ],
});
if (maybeRunReadmeCli("plugin-updater"))
    process.exit(0);
// remove repos/ clones and deployed plugin/ files for plugins no longer in
// plugins.json, so a removed/renamed plugin stops showing up
export function pruneOrphans(configDir, plugins) {
    const keep = new Set(plugins.map((p) => p.name));
    try {
        for (const dir of fs.readdirSync(getReposDir(configDir))) {
            if (!keep.has(dir)) {
                // Said before the removal, not only after: a clone carries its node_modules, so this
                // is the slow part of an uninstall and the only one worth watching.
                writeLog(`Removing repos/${dir}`);
                try {
                    fs.rmSync(path.join(getReposDir(configDir), dir), { recursive: true, force: true });
                    writeLog(`Pruned orphaned repos/${dir}`);
                }
                catch { /* ignore */ }
            }
        }
    }
    catch { /* no repos dir */ }
    const deployedIds = new Set(plugins.map((plugin) => deployedIdFor(getReposDir(configDir), plugin.name)));
    try {
        for (const file of fs.readdirSync(getPluginDir(configDir))) {
            // The deploy directory's own ESM marker, owned by no plugin.
            if (file === "package.json")
                continue;
            const suffix = DEPLOYED_SUFFIXES.find((candidate) => file.endsWith(candidate));
            if (!suffix)
                continue;
            if (deployedIds.has(file.slice(0, -suffix.length)))
                continue;
            try {
                fs.unlinkSync(path.join(getPluginDir(configDir), file));
                writeLog(`Pruned orphaned plugin/${file}`);
            }
            catch { /* ignore */ }
        }
    }
    catch { /* no plugin dir */ }
}
// re-exported public API (consumers import these from "plugin-updater")
export { getNpmPlugins, installNpmPlugin, uninstallNpmPlugin, updateNpmPlugin } from "./npm.js";
export { getPlugins, getPluginsPath } from "./config.js";
// A manifest is arbitrary on-disk data, so the fields registerApp depends on are
// checked here rather than asserted: a malformed block registers nothing instead of
// entering the registry half-formed.
function isAppDescriptor(value) {
    if (!value || typeof value !== "object" || Array.isArray(value))
        return false;
    const candidate = value;
    return (typeof candidate.id === "string" &&
        candidate.id.length > 0 &&
        typeof candidate.label === "string" &&
        Array.isArray(candidate.home?.candidates) &&
        candidate.home.candidates.length > 0);
}
// A loader's clone carries its app descriptor in its manifest (`app` block). Register
// it into the shared app registry so a dashboard discovers apps from the loaders
// installed here, with no hardcoded app list. Best-effort: a plugin without an
// `app` block (any non-loader) registers nothing.
export function registerAppFromClone(name, reposDir = getReposDir()) {
    const app = readCloneManifest(path.join(reposDir, name))?.app;
    if (isAppDescriptor(app))
        registerApp(app);
}
// Called whenever a plugin finishes installing or updating: announce it (as
// "installed" on a plugin's first clone, "updated" when a previous version
// existed) and keep the app registry in sync with the loaders on disk.
function onInstalled(name, version, previousVersion, trigger) {
    if (previousVersion !== null)
        emitPluginUpdated(name, previousVersion, version, trigger);
    else
        emitPluginInstalled(name, version, trigger);
    registerAppFromClone(name);
}
export async function updatePluginPublic(pluginName, gitUrl, branch, commitHash) {
    if (isOpencodeHookInvocation(pluginName))
        return {};
    writeLog(`Public API update call for ${pluginName}`);
    const configDir = getAppConfigDir(getAppName());
    const entry = getPlugins(configDir).find((p) => p.name === pluginName);
    const detected = readUpdateCache(configDir).plugins[pluginName]?.experimentalAvailable ?? null;
    const tracked = branch ?? resolveBranch(entry ?? {}, readUpdaterConfig(configDir), detected);
    const repoDir = path.join(getReposDir(configDir), pluginName);
    const previousVersion = fs.existsSync(repoDir) ? getLocalHead(pluginName) : null;
    // interval 0: an explicit update request must never fast-path-skip
    const result = updatePlugin(pluginName, gitUrl, tracked, commitHash ?? null, 0);
    if (!result.success) {
        const err = new Error(`could not set up ${pluginName} - see the updater log`);
        emitPluginUpdateFailed(pluginName, err);
        throw err;
    }
    // persist the pin so the NEXT earlyLaunch (a normal pull) doesn't undo this downgrade;
    // a plain "Update now" (no commitHash) clears any earlier pin so it can move past it
    if (commitHash)
        setPluginCommitHash(configDir, pluginName, commitHash);
    else
        setPluginCommitHash(configDir, pluginName, null);
    await deployToExecutionDir(pluginName, getPluginDir(configDir), result.changed, configDir);
    recordInstalledHead(configDir, pluginName);
    if (result.changed)
        onInstalled(pluginName, getLocalHead(pluginName), previousVersion, "manual");
    else
        registerAppFromClone(pluginName);
}
/**
 * Records what this home now has of a plugin, so its update badge is not read from nothing.
 *
 * @remarks
 * A check writes the cache for every plugin it looks at, but the very first install of one happens
 * before any check has ever seen it, so without this a freshly installed plugin reads as behind
 * until the next check comes round.
 */
function recordInstalledHead(configDir, pluginName) {
    try {
        const head = getLocalHead(pluginName);
        if (!head)
            return;
        const cache = readUpdateCache(configDir);
        const previous = cache.plugins[pluginName];
        cache.checkedAt = new Date().toISOString();
        cache.plugins[pluginName] = {
            kind: "git",
            installedVersion: previous?.installedVersion ?? null,
            localHead: head,
            remoteHead: head,
            latestVersion: previous?.latestVersion ?? null,
            updateAvailable: false,
            experimentalAvailable: previous?.experimentalAvailable ?? null,
            updatedAt: cache.checkedAt,
        };
        writeUpdateCache(configDir, cache);
    }
    catch { /* a stale badge is not worth failing a finished install over */ }
}
// The single answer both the dashboard and the loader TUI render from. They cannot share the
// pure helpers (one bundles this module, the other loads it at runtime), so they share this.
export function pluginChannelState(configDir, name) {
    const entry = getPlugins(configDir).find((p) => p.name === name);
    const experimentalAvailable = readUpdateCache(configDir).plugins[name]?.experimentalAvailable ?? null;
    if (!entry)
        return { onExperimental: false, experimentalAvailable };
    return {
        onExperimental: tracksExperimental(entry, readUpdaterConfig(configDir), experimentalAvailable),
        experimentalAvailable,
    };
}
// core-loader's downgrade TUI action calls this SYNCHRONOUSLY and expects a string
// ("" or "Success" = ok, anything else = an error message shown to the user), so it
// cannot be async. Checks out the pinned commit and persists it (setPluginCommitHash)
// so the pin survives the next earlyLaunch; deploy happens on the next restart.
export function downgrade(plugin, commitHash) {
    // opencode invokes every plugin export as a hook with a single context object;
    // our real calls always pass a commitHash string as the 2nd argument
    if (typeof commitHash !== "string" || !commitHash)
        return "";
    if (!plugin || !plugin.name || !plugin.url)
        return "invalid plugin";
    writeLog(`Downgrade requested for ${plugin.name} -> ${commitHash}`);
    try {
        const configDir = getAppConfigDir(getAppName());
        // interval 0: a downgrade must never fast-path-skip
        const result = updatePlugin(plugin.name, plugin.url, plugin.branch, commitHash, 0);
        if (!result.success)
            return `could not check out ${commitHash} for ${plugin.name} - see the updater log`;
        setPluginCommitHash(configDir, plugin.name, commitHash);
        try {
            emitPluginDowngraded(plugin.name, commitHash, configDir);
        }
        catch { /* never fail a completed downgrade */ }
        return "";
    }
    catch (e) {
        const msg = e.message ?? String(e);
        writeLog(`Failed to downgrade ${plugin.name}: ${msg}`, true);
        return msg;
    }
}
export function uninstallPlugin(configDir, name) {
    const file = getPluginsPath(configDir);
    const entries = fs.existsSync(file) ? JSON.parse(fs.readFileSync(file, "utf8")) : [];
    const entry = entries.find((e) => e.name === name);
    if (!entry)
        throw new Error(`plugin not found: ${name}`);
    const remaining = entries.filter((e) => e.name !== name);
    // read the version before pruning removes the clone it comes from
    const removedVersion = getLocalHead(name) || "";
    fs.writeFileSync(file, JSON.stringify(remaining, null, 2), "utf8");
    writeLog(`Uninstalled plugin ${name}`);
